--
-- Table structure for table `returns`
--

DROP TABLE IF EXISTS `returns`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `returns` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `return_number` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL,
  `sale_id` int(11) NOT NULL,
  `customer_id` int(11) DEFAULT NULL,
  `return_type` enum('CUSTOMER_RETURN','DAMAGED_ITEM','WRONG_ITEM','DEFECTIVE_ITEM','WARRANTY_RETURN','OTHER') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'CUSTOMER_RETURN',
  `return_date` date NOT NULL,
  `reason` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `subtotal` decimal(15,2) NOT NULL DEFAULT 0.00,
  `return_fee` decimal(15,2) NOT NULL DEFAULT 0.00,
  `refund_amount` decimal(15,2) NOT NULL,
  `refund_method` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `refund_provider` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `refund_reference_no` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `refund_status` enum('unrefunded','refunded','credit_issued','debt_reduced','exchange') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'unrefunded',
  `status` enum('draft','requested','approved','received','refunded','completed','rejected','cancelled') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'draft',
  `notes` text COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `created_by` int(11) NOT NULL,
  `approved_by` int(11) DEFAULT NULL,
  `approved_at` datetime DEFAULT NULL,
  `received_by` int(11) DEFAULT NULL,
  `received_at` datetime DEFAULT NULL,
  `refunded_by` int(11) DEFAULT NULL,
  `refunded_at` datetime DEFAULT NULL,
  `cancelled_by` int(11) DEFAULT NULL,
  `cancelled_at` datetime DEFAULT NULL,
  `cancel_reason` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `is_restocked` tinyint(1) NOT NULL DEFAULT 0,
  `exchange_sale_id` int(11) DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `return_number` (`return_number`),
  KEY `created_by` (`created_by`),
  KEY `approved_by` (`approved_by`),
  KEY `idx_return_number` (`return_number`),
  KEY `idx_return_date` (`return_date`),
  KEY `fk_returns_received_by` (`received_by`),
  KEY `fk_returns_refunded_by` (`refunded_by`),
  KEY `fk_returns_cancelled_by` (`cancelled_by`),
  KEY `fk_returns_exchange_sale` (`exchange_sale_id`),
  KEY `idx_returns_sale` (`sale_id`),
  KEY `idx_returns_customer` (`customer_id`),
  KEY `idx_returns_status` (`status`),
  KEY `idx_returns_date` (`return_date`),
  KEY `idx_returns_created_status` (`created_at`,`status`),
  CONSTRAINT `fk_returns_cancelled_by` FOREIGN KEY (`cancelled_by`) REFERENCES `users` (`id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `fk_returns_exchange_sale` FOREIGN KEY (`exchange_sale_id`) REFERENCES `sales` (`id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `fk_returns_received_by` FOREIGN KEY (`received_by`) REFERENCES `users` (`id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `fk_returns_refunded_by` FOREIGN KEY (`refunded_by`) REFERENCES `users` (`id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `returns_ibfk_1` FOREIGN KEY (`sale_id`) REFERENCES `sales` (`id`) ON UPDATE CASCADE,
  CONSTRAINT `returns_ibfk_2` FOREIGN KEY (`customer_id`) REFERENCES `customers` (`id`) ON UPDATE CASCADE,
  CONSTRAINT `returns_ibfk_3` FOREIGN KEY (`created_by`) REFERENCES `users` (`id`) ON UPDATE CASCADE,
  CONSTRAINT `returns_ibfk_4` FOREIGN KEY (`approved_by`) REFERENCES `users` (`id`) ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=57 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

